<?php namespace App\Policies; use App\Models\{User,AcademicSubjectEnrollment}; class AcademicSubjectEnrollmentPolicy {public function viewAny(User $u):bool{return $u->hasPermission('academic_subject_enrollments.view');} public function view(User $u,AcademicSubjectEnrollment $m):bool{return $u->hasPermission('academic_subject_enrollments.view',$m->college_id);} public function create(User $u):bool{return $u->hasPermission('academic_subject_enrollments.create');} public function update(User $u,AcademicSubjectEnrollment $m):bool{return $u->hasPermission('academic_subject_enrollments.update',$m->college_id);} public function delete(User $u,AcademicSubjectEnrollment $m):bool{return $u->hasPermission('academic_subject_enrollments.delete',$m->college_id);}}
